--- 筛选卡牌数据
---@param self UIFightChooseCardsDialog
---@param sortType number
local function FilterData(self, sortType, asc)
    --过滤数据
    ---@type ECSWorldMgr
    local worldMgr = ECSWorldMgr:GetInstance()
    ---@type ECSWorld
    local world = worldMgr:GetWorld(Constants.GameWorld)
    ---@type ECSEntity
    local entity = world:GetEntity(Constants.PlayerEntityId)
    ---@type CardComponent
    local cardComp = entity:GetComp(ECSComponentType.Constants.CardComponent)
    if not isNull(cardComp) then
        self.haveCard = CardUtils.SortCardBySortType(self.haveCard, sortType, asc)
    end
end

