    self._targetCardId = 0    --目标卡牌id 用来选羁绊位
    self._curFettersId = 0    --当前的羁绊id

    ---@type CardDojo[]
    self._customCardDojos = nil  -- 自定义：卡牌列表数据
    self._customSelectIds = {}   -- 自定义：选中的卡牌id列表
    ---@type table<string, string>
    self._customSelectMap = {}   -- 自定义：选中的卡牌位置map（key：cardId，value：index）
    self._customLimitNum  = 0    -- 自定义：卡牌的选择上限数
