function UIFightChooseCardsDialog:OnRegionTeamSet()
    if self._isSetTeamReq then
        if self._confirmCb then self._confirmCb() end
        UIModule.BackDialog()
    end
end

function UIFightChooseCardsDialog:OnFocus(focus)
    if focus then
        -- 定向研究
        if self.chooseCardStatus == Constants.ChooseCardStatus.DirectDraw then
            ---@type UINavigatorBar
            local UINavigatorBar = CfUtils.GetLuaScr(UINavigationBarRoot.Instance.gameObject, "Game.Main.UINavigatorBar")
            UINavigatorBar:CustomTitleName(localize("研究方向变更"))
        end
    end
end

function UIFightChooseCardsDialog:Awake()
    self.curSelectIndex = checkNumber(KCookie.Get("UIFightChooseCardsDialogSelectInd")) --统一改为从1开始算

    ---@type UIFightChooseCardsLeftNode
    self._uiFightChooseCardsLeftNode = CfUtils.GetLuaScr(self.LeftRoot, UIFightChooseCardsLeftNode)
    ---@type UIFightChooseCardsFishNode
    self._uiFightChooseCardsFishNode = CfUtils.GetLuaScr(self.Fishing, UIFightChooseCardsFishNode)
    ---@type UIFightChooseCardsCatTrainNode
    self._uiFightChooseCardsCatTrainNode = CfUtils.GetLuaScr(self.CatHouseTrain, UIFightChooseCardsCatTrainNode)
    ---@type UIFightChooseCardsFetterNode
    self._uiFightChooseCardsFetterNode = CfUtils.GetLuaScr(self.FetterInfo, UIFightChooseCardsFetterNode)

    self.EventUIFightChooseCardsDialogAct = Events.AddListener(Constants.EventNames.FightChooseCardsDialogAct, Bind(self, self.OnUIFightChooseCardsDialogAct))
    self.EventFishHangUpTimeDown = Events.AddListener(Constants.EventNames.FishHangUpTimeDown, Bind(self, self.OnFishHangUpTimeDown))
    self.EventRegionTeamSet = Events.AddListener(Constants.EventNames.RegionTeamSet, Bind(self, self.OnRegionTeamSet))
    self.EventEquipmentUpdate = Events.AddListener(Constants.EventNames.EquipmentPresetDialogUpdate, Bind(self, self.OnEquipmentUpdate))

    local argument = CfUtils.DialogSafeParameters(self.controller)
    self.chooseCardStatus = checkNumber(argument.chooseCardStatu)
    self._backIsClose = argument.backIsClose
    self._curLevelId = checkNumber(argument.levelId)    --关卡ID
    self._teamIndex = argument.teamIndex    --位置ID
    self.catData = argument.catData
    self.catRolesData = argument.catRolesData
    if checkNumber(self._teamIndex) == 0 then
        self._teamIndex = 1
    end
    if argument._curSelectIndex ~= nil then
        self.curSelectIndex = argument._curSelectIndex
    end

    self._activityUuid = checkNumber(argument.activityUuid)
    self._upBuffData = argument.upBuffData  -- 通用的增益buff数据
    self._confirmCb = argument.confirmCb -- 确认回调
    self._closeCb = argument.closeCb -- 关闭回调
    self._teamType = argument.teamType
    self._patrolMaze = argument.patrolMaze

    self._uiFightChooseCardsLeftNode:SetPatrolMaze(self._patrolMaze)

    ---卡牌编队不会变更猫球 这里直接缓存下
    local isShowCatBall = QuestConfMgr:GetInstance():IsShowCatBall(self._curLevelId)
    ---@type TeamCatBallDojo[]
    local teamCats
    if isShowCatBall then
        teamCats = teamComponent:GetTeamCatByQuestId(self._curLevelId, self._teamIndex)
        local catEggComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatEggComponent)
        for index, value in ipairs(teamCats) do
           if checkNumber(value.playerCatId) > 0 then
               ---@type CatEggDojo
               local catEggDojo = catEggComponent:GetCatById(value.playerCatId)
               value:SetStar(catEggDojo.star)
           end
        end
    end
    self._teamCats = teamCats

    -- 禁用卡片id列表
    self._disableIdMap = {}
    for _, cardId in ipairs(argument.disableIdList or {}) do
        self._disableIdMap[tostring(cardId)] = true
    end

    KTool.SetActive(self.ToFight, false)
    KTool.SetActive(self.NoSelect, true)

    if isNull(teamComponent) then
        teamComponent = playerComponent.entity:GetOrAddComp(ECSComponentType.Constants.TeamComponent)
    end
    local t
    --钓鱼陪钓
    if self.chooseCardStatus == Constants.ChooseCardStatus.FishAccompany then
        KTool.SetActive(self.Fishing, true)
        KTool.SetActive(self.TotalTeam, false)
        self._curFishPlaceId = checkNumber(argument.placeId)    --渔场id
        local dojo = FishingUtils.GetFishingPlaceDojo(self._curFishPlaceId)
        if dojo then
            if checkNumber(dojo.partner) > 0 then
                local cardDojo = cardComponent:GetCardById(dojo.partner)
                if cardDojo then
                    self._curSelectCardId = checkNumber(cardDojo.cardId)
                end
            end
        end

        KTool.SetActive(self.CommonFilterNode.gameObject, false)
    --挂机
    elseif self.chooseCardStatus == Constants.ChooseCardStatus.FishHangeUp then
        KTool.SetActive(self.Fishing, true)
        KTool.SetActive(self.TotalTeam, false)
        
        self._curFishQueueId = checkNumber(argument.queueId)    --队列id
        t = FishingUtils.GetFishTeamByHangUpQueueId(self._curFishQueueId)
        teamComponent:InitBufferTeam(t)
    --委托
    elseif self.chooseCardStatus == Constants.ChooseCardStatus.Entrust then
        KTool.SetActive(self.LeftRoot, true)
        self._entrustId = checkString(argument.entrustId)
        t = teamComponent:GetEntrustTeamData(self._entrustId)

        KTool.SetActive(self.TotalTeam, true)
        teamComponent:InitBufferTeam(t)
        self:FillSelf()
        self:SetLeftInfoLevel()
    --猫屋训练
    elseif self.chooseCardStatus == Constants.ChooseCardStatus.CatHouseTrain then
        KTool.SetActive(self.CatHouseTrain, true)
        KTool.SetActive(self.TotalTeam, false)
        KTool.SetActive(self.ToFight, true)
        local isEmpty = true
        --print("catRolesData------>>"..table.dump(self.catRolesData))
        for i, v in pairs(checkTable(self.catRolesData)) do
            if table.count(v) ~= 0 then
                isEmpty = false
                break
            end
        end
        if not isEmpty then
            t = self.catRolesData
            self:RefreshCatTrainShowInfo(self.catRolesData[1])
            local co = cs_coroutine.start(function()
                cs_coroutine.yield_return(Yielders.EndOfFrame)
                self:CatSubjoinAttrChanged(self.catRolesData)
            end)
        end
        teamComponent:InitBufferTeam(t)
        self:FillChooseCatNumber()
        if not isNull(self._uiFightChooseCardsCatTrainNode) then
            self._uiFightChooseCardsCatTrainNode:SetInitialAttrPanel(self.catData)
        end


        --self.TxtTitle.Status = SwitchTextStatusTxtTitle.cathouse
        ----CfUtils.FillText(self.TxtNum, string.format("s%/s%", ))--当前数量/最大数量

    -- 天梯竞技
    elseif self.chooseCardStatus == Constants.ChooseCardStatus.LadderCompetion then
        KTool.SetActive(self.LeftRoot, true)
        KTool.SetActive(self.TotalTeam, true)
        KTool.SetActive(self.ToFight, true)

        t = teamComponent:GetTeamByQuestId(self._curLevelId, self._teamIndex)
        teamComponent:InitBufferTeam(t)

        self:FillSelf()  -- power
        self:FillChooseNumber()
        self:FillBg()

    -- 定向研究
    elseif self.chooseCardStatus == Constants.ChooseCardStatus.DirectDraw then
        KTool.SetActive(self.LeftRoot, true)   -- 显示左侧栏
        KTool.SetActive(self.TotalTeam, false) -- 关闭总战力
        KTool.SetActive(self.CommonFilterNode.gameObject, false)    -- 关闭过滤节点
        ---@type ActivityDirectDrawComponent
        self._directDrawComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityDirectDrawComponent)
        local cardDojo = self._directDrawComponent:GetCurDrawCardDojo()
        if cardDojo then
            self._curSelectCardId = checkNumber(cardDojo.cardId)
        end

    -- 自定义
    elseif self.chooseCardStatus == Constants.ChooseCardStatus.Custom then
        self._customLimitNum  = checkInt(argument.customLimitNum)
        self._customLeastNum  = checkInt(argument.customLeastNum)
        self._customCardDojos = checkTable(argument.customCardDojos)
        self._customSelectIds = argument._customSelectIds ~= nil and table.deserialize(argument._customSelectIds) or clone(argument.customSelectIds or {})
        self._customCheckSame = checkBool(argument.customCheckSame)
        self._customSelectMap = {}
        for cardIndex, cardId in ipairs(self._customSelectIds) do
            self._customSelectMap[tostring(cardId)] = tostring(cardIndex)
        end
        -- 单选模式，默认找到选中的位置
        if self._customLimitNum == 1 then
            local customSelectId = checkInt(self._customSelectIds[1])
            if customSelectId > 0 then
                for cardIndex, cardDojo in ipairs(self._customCardDojos) do
                    if checkInt(cardDojo.cardId) == customSelectId then
                        self.curSelectIndex = cardIndex
                        break
                    end
                end
            end
        end
        self.TxtTitle.Status  = SwitchTextStatusTxtTitle.cathouse  -- 选择文字的样式
        KTool.SetActive(self.LeftRoot, true)   -- 显示左侧栏
        KTool.SetActive(self.TotalTeam, false) -- 关闭总战力
        CfUtils.SetActive(self.CardEquip, false)  -- 关闭装备
        self._uiFightChooseCardsLeftNode:SetOpenPreview(true)  -- 显示预览
        if self._customLimitNum > 1 then
            KTool.SetActive(self.ToFight, true)    -- 选中的数量
            self:FillChooseCustomNumber()          -- 更新选中数量
        else
            KTool.SetActive(self.ToFight, false)
        end
        KTool.SetActive(self.CommonFilterNode, false)  -- 关闭过滤按钮
        if self._curLevelId > 0 then
            self:SetLeftInfoLevel()
        end
    --羁绊
    elseif self.chooseCardStatus == Constants.ChooseCardStatus.Fetter then
        self._targetCardId = checkNumber(argument.targetCardId)    --目标卡牌id 用来选羁绊位

        KTool.SetActive(self.LeftRoot, true)
        if self:IsPresetTeam() then
            t = teamComponent:GetTeamByTeamType(self._teamType, self._teamIndex)
            KTool.SetActive(self.TotalTeam, true)
            teamComponent:InitBufferTeamByTeamType(t, self._teamType)
        else
            self._curLevelType = GoodsUtils.GetIdType(self._curLevelId, Constants.IDArea.Quests)     --关卡类型
            if AnnihilationUtils.QuestTypeIsAnnihilation(self._curLevelType) then
                t = RegionQuestMgr:GetInstance():GetOwnTeam(false)
            else
                t = teamComponent:GetTeamByQuestId(self._curLevelId, self._teamIndex, { isDontNeedHelper = false })
            end

            KTool.SetActive(self.TotalTeam, true)
            teamComponent:InitBufferTeam(t, self._curLevelId)
        end

        local dojo
        local id = teamComponent:GetTeamFettersId(t, self._targetCardId)
        if checkNumber(id) <= 0 then
            self._curFettersId = 0
        else
            dojo = cardComponent:GetCardById(id)
            self._curFettersId = checkNumber(dojo.cardId)
        end


        self._powerTeam = clone(teamComponent:GetBufferTeam())
        self:FillSelf()
        self:SetLeftInfoLevel()
        self:FillChooseNumber()
        self:FillBg()

        self:RefeshFettersInfo(dojo)

    --正常选人
    else
        KTool.SetActive(self.LeftRoot, true)
        KTool.SetActive(self.TotalTeam, true)
        if self._patrolMaze then
            self._uiFightChooseCardsLeftNode:SetOpenPreview(true)  -- 显示预览
        end
        
        self._curLevelType = GoodsUtils.GetIdType(self._curLevelId, Constants.IDArea.Quests)     --关卡类型
        if AnnihilationUtils.QuestTypeIsAnnihilation(self._curLevelType) then
            t = RegionQuestMgr:GetInstance():GetOwnTeam()
            teamComponent:InitBufferTeam(t)

        else
            if self:IsPresetTeam() then
                t = teamComponent:GetTeamByTeamType(self._teamType, self._teamIndex)
                teamComponent:InitBufferTeamByTeamType(t, self._teamType)
            else
                t = teamComponent:GetTeamByQuestId(self._curLevelId, self._teamIndex, { isDontNeedHelper = false })
                teamComponent:InitBufferTeam(t)
            end
        end
        if argument._bufferTeam ~= nil then
            teamComponent._bufferTeamTab = argument._bufferTeam
        end

        self:FillSelf()
        self:SetLeftInfoLevel()

        KTool.SetActive(self.ToFight, true)
        self:FillChooseNumber()
        self:FillBg()
    end

    teamComponent:InitDefaultTeam(t)

    self:RefeshCardsData()
    if not self.haveCard then
        return
    end
    --排序
    -- self:FillFilter()

    ---取消按钮
    SetButtonAction(self.FontStyleWithIconButton2, function()
        --关闭界面
        UIModule.BackDialog()
    end)  

    --确定按钮
    SetButtonAction(self.FontStyleWithIconButton1, Bind(self, self.OnBtnSure))

    -- 预览按钮
    self._uiFightChooseCardsLeftNode:SetClickOpenPreviewCb(Bind(self, self.OnBtnPreview))
    
    -- 刷新情绪共鸣节点
    if not CardUtils.IsUseEmotionBonus(self.chooseCardStatus) then
        CfUtils.SetActive(self.FightTeamBonusNode, false)
        if argument._curSelectIndex ~= nil then
            local chooseCardDojo = self.haveCard[self.curSelectIndex]
            if self.chooseCardStatus == Constants.ChooseCardStatus.Custom then
                self:RefeshCustomCardShowInfo(chooseCardDojo)
            else
                self:RefeshCardShowInfo(chooseCardDojo)
            end
        end
    else
        CfUtils.SetActive(self.FightTeamBonusNode, true)
        GameUtils.RefreshLineupBonusNode(self.FightTeamBonusNode, teamComponent:GetBufferTeam(), false, false)
    end
end

function UIFightChooseCardsDialog:ChooseDirectDrawCard(index, go)
    if not index then
        return
    end
    local luaIndex = index + 1
    local cellData = self._directDrawCardPool[luaIndex]

    local lastSelectIndex = checkNumber(self.curSelectIndex)
    self.curSelectIndex = checkInt(index) + 1

    self._curSelectCardId = cellData.cardId

    self.ChooseCardsView:SetListItemCount(table.count(self._directDrawCardPool))

    if checkNumber(lastSelectIndex) >= 0 then
        go = self.ChooseCardsView:GetShownItemByItemIndex(lastSelectIndex)
        if go then
            local lastScr = CfUtils.GetLuaScr(go, UIFightChooseCardsCardCellNode)
            if lastScr then
                lastScr:RefreshImgSelectStatu(false)
            end
        end
    end

    local curSelectInd = checkNumber(self.curSelectIndex)
    if checkNumber(curSelectInd) > 0 then
        go = self.ChooseCardsView:GetShownItemByItemIndex(curSelectInd-1)
        if go then
            local curScr = CfUtils.GetLuaScr(go, UIFightChooseCardsCardCellNode)
            if curScr then
                curScr:RefreshImgSelectStatu(true)
            end
        end
    end

    -----@type UIFightChooseCardsLeftNode
    --local scr = CfUtils.GetLuaScr(self.LeftRoot, "Game.UI.FightTeam.UIFightChooseCardsDialog.UIFightChooseCardsLeftNode")
    --
    -----@type CardDojo
    --local cardDojo = CardConfMgr:GetInstance():GetCardByRefId(cellData.cardId)
    --cardDojo.cardId = cellData.cardId
    --
    --scr:RefreshDirectDrawLeftInfo(cardDojo)

    --self:FreshCurTeamXielizhi()
    --刷新右边人物信息
    --self:RefeshCardShowInfo(cellData, false)

    --self:FillChooseNumber()
    KCookie.Set("UIFightChooseCardsDialogSelectInd", checkNumber(self.curSelectIndex))
end

function UIFightChooseCardsDialog:RefreshDirectDrawItemByIndex(go, index)
    local luaIndex = index + 1
    --local directDrawCardData = self.directDrawCardPool[luaIndex]
    local directDrawCardData = self._directDrawCardPool[luaIndex]
    ---@type UIFightChooseCardsCardCellNode
    local scr = CfUtils.GetLuaScr(go, UIFightChooseCardsCardCellNode)
    scr:RefreshDirectDraw(directDrawCardData, function(isCanDel)
        --self:ChooseCards(index, go, isCanDel)
        self:ChooseDirectDrawCard(index, go)
    end)

    if checkNumber(self.curSelectIndex) == 0 and checkNumber(self._curSelectCardId) == checkNumber(directDrawCardData.cardId) then
        self.curSelectIndex = luaIndex
    end

    scr:RefreshCurrentGoStatu(self.curSelectIndex == luaIndex)
    scr:RefreshChooseStatu(self.curSelectIndex == luaIndex)
    scr:RefreshImgSelectStatu(self.curSelectIndex == luaIndex)
end

function UIFightChooseCardsDialog:OnShow()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        if not KTool.IsNull(self.ChooseCardsView) then
            if self.chooseCardStatus == Constants.ChooseCardStatus.DirectDraw then
                ---@type ActivityDirectDrawComponent
                self._directDrawComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityDirectDrawComponent)
                local directDrawHomeDojo = self._directDrawComponent:GetDirectDrawHomeDojo()
                self._directDrawCardPool = directDrawHomeDojo.choseCardIds
                for i, id in ipairs(self._directDrawCardPool) do
                    self._directDrawCardPool[i] = {
                        cardId = id
                    }
                end
                self._curSelectCardId = directDrawHomeDojo.playerChoseCardId
