                self.haveCard = self:GetAllCard(self.haveCard)
                local count = table.count(self.haveCard)
                self.ChooseCardsView:InitListView(count, Bind(self, self.OnGetItemByIndex), nil, Bind(self, self.OnGetListItemByIndex), 5)
            end
            CfUtils.ReloadRowCountAutoFix(self.ChooseCardsView)
        end
        
        -- 改为内部 OnBackAction 方法实现了
        -- CfUtils.RefreshTopCommon(function()
        --     if checkNumber(self._backIsClose) == 1 then
        --         UIModule.CloseDialog(self.controller)
        --         Events.Broadcast(Constants.EventNames.UIEntrustBattleTeamDialogActive, { isTrue = true })
        --     else
        --         UIModule.BackDialog()
        --     end
        -- end, false)

        Events.Broadcast(Constants.EventNames.UIMainHomeSceneFocusShowEventName, false)
    end))
    return coWait
end

function UIFightChooseCardsDialog:OnBackAction()
    if checkNumber(self._backIsClose) == 1 then
        UIModule.CloseDialog(self.controller)
        Events.Broadcast(Constants.EventNames.UIEntrustBattleTeamDialogActive, { isTrue = true })
    end
end

