function UIFightChooseCardsDialog:FillSelf(isAni)
    --if self._curLevelType == Constants.IDType.QuestSeniorEquipCopy then
    --    KTool.SetActive(self.FastRelief, true)
    --    self._uiFightChooseCardsFastReliefNode = CfUtils.GetLuaScr(self.FastRelief, UIFightChooseCardsFastReliefNode)
    --    self:FreshCurTeamXielizhi()
    --end
    local vo = QuestConfMgr:GetInstance():GetQuestVoById(self._curLevelId)   --关卡配置
    local proposalLevel = vo == nil and 0 or checkNumber(vo.proposalLevel)
    
    if isAni then
        local fNum = self._lastNum
        if self.chooseCardStatus ~= Constants.ChooseCardStatus.Fetter then
            self._lastNum = teamComponent:GetTeamFightingPower(teamComponent:GetBufferTeam(), self._teamCats, vo)
        else
            self._lastNum = teamComponent:GetTeamFightingPower(self._powerTeam, self._teamCats, vo)
        end

        local tNum = self._lastNum
        local dis = tNum - fNum
        CfUtils.DoTween(0.5, function(value)
            CfUtils.FillText(self.TxtNumber, checkInt(fNum + dis * value))
        end, function()
            local isLowPower = (self._lastNum < proposalLevel)
            if self._curLevelType == Constants.IDType.QuestNightCatTower then
                isLowPower = false
            end
            CfUtils.SetUISwitchText(self.TxtNumber, isLowPower and 2 or 1)
            --CfUtils.SetActive(self.LowNumber, isLowPower)

            CS.Engine.UI.UIRaycastBlocker.Instance:RemoveCondition("UIFightChooseCardsDialogPowerChange")
        end, function()
            local isLowPower = (self._lastNum < proposalLevel)
            if self._curLevelType == Constants.IDType.QuestNightCatTower then
                isLowPower = false
            end
            CfUtils.SetUISwitchText(self.TxtNumber, isLowPower and 2 or 1)
            --CfUtils.SetActive(self.LowNumber, isLowPower)

            CS.Engine.UI.UIRaycastBlocker.Instance:AddCondition("UIFightChooseCardsDialogPowerChange")
        end)
    else
        self._lastNum = teamComponent:GetTeamFightingPower(teamComponent:GetBufferTeam(), self._teamCats, vo)
        CfUtils.FillText(self.TxtNumber, self._lastNum)

        local isLowPower = (self._lastNum < proposalLevel)
        if self._curLevelType == Constants.IDType.QuestNightCatTower then
            isLowPower = false
        end
        CfUtils.SetUISwitchText(self.TxtNumber, isLowPower and 2 or 1)
        --CfUtils.SetActive(self.LowNumber, isLowPower)
    end
end

--初始化卡牌数据
function UIFightChooseCardsDialog:RefeshCardsData()
    self.haveCard = {}
    
    ---@type CardDojo[]
    local cards = nil
    if self._curLevelType == Constants.IDType.QuestMaze then --迷宫
        local mazeTeamComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MazeTeamComponent, Constants.MazeTeamEntityId)
        cards = mazeTeamComp:GetRolesArr()
    elseif self._curLevelType == Constants.IDType.QuestPatrolMaze then  -- 海外夜巡
        ---@type PatrolMazeAreaDojo @ 当前所在区域dojo
        local areaDojo = self._patrolMaze.areaDojo
        cards = areaDojo:GetAliveCardDojoList()
    elseif self.chooseCardStatus == Constants.ChooseCardStatus.FishAccompany or self.chooseCardStatus == Constants.ChooseCardStatus.FishHangeUp then
        local t = FishingUtils.GetAllFishCard()
        cards = {}
        for k, v in pairs(t) do
            local vo = CardConfMgr:GetInstance():GetCardByRefId(v.id)
            table.insert(cards, vo)
        end
        cards = self:GetFishAllSortCard(cards)
    elseif self.chooseCardStatus == Constants.ChooseCardStatus.CatHouseTrain then
        local t = CfUtils.GetWholeVo(AutoIds.IdSetting1915, "CatCardTrainSkillVo")
        cards = {}
        for k, v in pairs(t) do
            local data
            data = CardConfMgr:GetInstance():GetCardByRefId(v.id)
            if data then
                data["id"] = v.id
                if cardComponent:IsHasCard(v.id) then
                    local cardDojo = cardComponent:GetCardById(cardComponent:GetIdByCardId(data.refId))
                    data["star"] = cardDojo.star--加入星级数据用于排序
                    data["typePriority"] = 3
                    --table.insert(cards, 1, data)
                else
                    data["star"] = 0
                    data["typePriority"] = 1
                end
                table.insert(cards, data)
            end
        end
        cards = CardUtils.SortCardTrainBySortType(cards, Constants.SortType.Star, true)
    elseif self.chooseCardStatus == Constants.ChooseCardStatus.Fetter then
        cards = {}
        local t = cardComponent:GetAllCardTable()

        local targetVo = CardConfMgr:GetInstance():GetCardByRefId(self._targetCardId)
        for k, v in pairs(t) do
            if checkNumber(teamComponent:GetTeamCardKey(teamComponent:GetBufferTeam(), v.id)) == 0 and
              checkNumber(teamComponent:GetTeamCardKey(teamComponent:GetBufferTeam(), v.cardId)) == 0 and 
              not teamComponent:IsHelpFettersCardUse(teamComponent:GetBufferTeam(), v.cardId) then
                if teamComponent:IsUseOldTeams(self._curLevelId) then
                    local isInTeam, teamIndex = teamComponent:IsCardInAllTeam(self._curLevelId, v.id)
                    if isInTeam and checkNumber(teamIndex) ~= checkNumber(self._teamIndex) then
                    else
                        local vo = CardConfMgr:GetInstance():GetCardByRefId(v.cardId)
                        if vo and checkNumber(vo.characterId) ~= checkNumber(targetVo.characterId) then
                            table.insert(cards, v)
                        end
                    end
                else
                    local vo = CardConfMgr:GetInstance():GetCardByRefId(v.cardId)
                    if vo and checkNumber(vo.characterId) ~= checkNumber(targetVo.characterId) then
                        table.insert(cards, v)
                    end
                end
            end
        end
        cards = self:GetFettersAllSortCard(cards)
    elseif self._curLevelId == Constants.SpecialQuestId.LadderStruggleId or self._curLevelId == Constants.SpecialQuestId.ClubGVGId then
        cards = {}
        local t = cardComponent:GetAllCardTable()
        for k, v in pairs(t) do
            local isInTeam, teamIndex = teamComponent:IsCardInAllTeam(self._curLevelId, v.id)
            if not isInTeam or checkNumber(teamIndex) == checkNumber(self._teamIndex) then
                table.insert(cards, v)                    
            end
        end
    elseif self._curLevelType == Constants.IDType.QuestTower then
        -- 处理限制属性卡牌机制
        cards = clone(cardComponent:GetAllCardTable())
        local OverseaTowerUtils = import('Game.UI.FightReady.OverseaTower.OverseaTowerUtils')
        local questVo = OverseaTowerUtils.GetTowerQuestVo(self._curLevelId)
        local towerTypeVo = OverseaTowerUtils.GetTowerTypeVo(questVo.type)
        local limitAttr = checkTable(towerTypeVo.limitAttr)
        if next(limitAttr) then
            for _, v in pairs(cards) do
                local usable = false
                for _, attrId in ipairs(limitAttr) do
                    local cardVo = CardConfMgr:GetInstance():GetCardByRefId(v.cardId)
                    if cardVo.attributeType == attrId then
                        usable = true
                        break
                    end
                end
                v.usable = usable and 1 or 0
            end
        end
    elseif self._curLevelType == Constants.IDType.QuestMain then
        cards = clone(cardComponent:GetAllCardTable())
        for _, v in pairs(cards) do
            v.usable = 1
        end
        -- 处理主线关卡限制属性的情况
        local vo = QuestConfMgr:GetInstance():GetQuestVoById(self._curLevelId) or {}
        local limitVo = QuestConfMgr:GetInstance():GetQuestTeamLimitVo(vo.roleRestrictions) or {}
        for i = 1, 4 do
            local type = limitVo["type"..i]
            local attrId = limitVo["attribute"..i]
            if checkInt(attrId) > 0 then
                --检测目标类型
                if checkNumber(type) == Constants.TeamLimitType.Must then
                    for _, v in pairs(cards) do
                        local cardVo = CardConfMgr:GetInstance():GetCardByRefId(v.cardId)
                        if cardVo.attributeType ~= attrId then
                            v.usable = 0
                        end
                    end
                elseif checkNumber(type) == Constants.TeamLimitType.Limit then
                    for _, v in pairs(cards) do
                        local cardVo = CardConfMgr:GetInstance():GetCardByRefId(v.cardId)
                        if cardVo.attributeType == attrId then
                            v.usable = 0
                        end
                    end
                end
            end
        end
    elseif self._curLevelType == Constants.IDType.Fairyland then
        cards = clone(cardComponent:GetAllCardTable())
        for _, v in pairs(cards) do
            for i = 1, 6 do
                v["equipment" .. tostring(i)] = 0
            end
        end
    else
        if self._customCardDojos then
            cards = self._customCardDojos
        else
            cards = cardComponent:GetAllCardTable()
            if self._upBuffData then
                for _, v in ipairs(cards) do
                    v.isUp = QuestConfMgr:GetInstance():IsCardUp(v.cardId, self._upBuffData) and 1 or 0
                end
            end
        end
    end

    if not cards then
        self.haveCard = {}
        return
    end

    --[[
    if self.chooseCardStatu == Constants.ChooseCardStatus.FishHangeUp then
        for k, v in pairs(cards) do 
            if FishingUtils.IsCardCanFishing(v.cardId) then
                table.insert(self.haveCard, v)
            end
        end
    else
        self.haveCard = cards
    end
    ]]

    local listCard = {}
    --正常选人要加机器人
    if self.chooseCardStatus == Constants.ChooseCardStatus.Normal then
        if QuestConfMgr:GetInstance():IsQuestHasHelper(self._curLevelId) then
            local teamCards = QuestConfMgr:GetInstance():GetQuestHelpers(self._curLevelId)
            for k, v in pairs(teamCards) do
                local vo = CardConfMgr:GetInstance():GetCardByRefId(v.cardId)
                --vo.isAssistant = Constants.MazeRole.AssistRole 
                --vo.cardId = v.cardId
                --vo.id = v.cardId

                local dojo = CardDojo.New()
                dojo.cardSkin = vo.defaultSkin
                dojo.isAssistant = Constants.MazeRole.AssistRole 
                dojo:Fill(vo)
                dojo.cardId = v.cardId
                dojo.id = v.cardId
                
                table.insert(listCard, dojo)
            end
        end

        table.insertto(listCard, clone(cards))
    else
        listCard = clone(cards)
    end

    self.haveCard = listCard
end

function UIFightChooseCardsDialog:OnGetListItemByIndex(go)
    if isNull(go) then
        return
    end
    local rt = go.gameObject:GetComponent(typeof(RectTransform))
    if (self._curLevelType == Constants.IDType.QuestMaze or
        self._curLevelType == Constants.IDType.QuestPatrolMaze or
        self._curLevelType == Constants.IDType.QuestSeniorEquipCopy or
        self._curLevelType == Constants.IDType.QuestTalent) then
        rt:SetSizeWithCurrentAnchors(RectTransform.Axis.Vertical, 300)
    else
        rt:SetSizeWithCurrentAnchors(RectTransform.Axis.Vertical, 268)
    end
end

---设置所有卡牌信息
function UIFightChooseCardsDialog:OnGetItemByIndex(go, index, row, column)
    if index < 0 then
        return
    end
    local cellCardData = self.haveCard[index + 1]
    ---@type UIFightChooseCardsCardCellNode
    local scr = CfUtils.GetLuaScr(go, UIFightChooseCardsCardCellNode)
    if scr then
        if self.chooseCardStatus == Constants.ChooseCardStatus.FishAccompany then
            scr:RefreshFishAccompany(cellCardData, function()
                if not FishingUtils.IsCardGetAndCanFishing(cellCardData.cardId) then
                    --GameUtils.Toast(localize("未解锁该角色"))
                    --return
                end
                self:ChooseFishAccompanyCard(index)
            end, self._curFishQueueId)
        elseif self.chooseCardStatus == Constants.ChooseCardStatus.FishHangeUp then
            scr:RefreshFishHangUp(cellCardData, function()
                self:ChooseFishHangUpCards(index, go)
            end, self._curFishQueueId)
            scr:RefreshImgSelectStatu(self.curSelectIndex == index+1)
        elseif self.chooseCardStatus == Constants.ChooseCardStatus.CatHouseTrain then
            --scr:Refresh(cellCardData, function(isCanDel)
            --    self:ChooseCards(index, go, isCanDel)
            --end, self._curFishQueueId)
            --print("====>>"..table.dump(cellCardData))
            scr:RefreshCatTrain(cellCardData, function(isCanDel)
                --print("cellCardData====>>"..table.dump(cellCardData))
                --local cardId = cellCardData.cardId or cellCardData.refId --角色卡片表中叫refId
                local isHaveCard = cardComponent:IsHasCard(cellCardData.refId)
                if isHaveCard then
                    self:ChooseCards(index, go, isCanDel)
                else
                    GameUtils.Toast(localize("未解锁该角色"))
                    return
                end
            end)
        elseif self.chooseCardStatus == Constants.ChooseCardStatus.Fetter then
            scr:RefreshFettersInfo(cellCardData, function(isCanDel)
                self:ChooseFettersCard(index)
            end, function()
                teamComponent:ChangeTeamFettersByCardId(teamComponent:GetBufferTeam(), self._targetCardId, 0)
                self._curFettersId = 0
                self.ChooseCardsView:SetListItemCount(table.count(self.haveCard))
                scr:RefreshImgSelectStatu(false)
                scr:RefreshChooseStatu(false)
                self.curSelectIndex = 0

                self._powerTeam = clone(teamComponent:GetBufferTeam())
                self:RefeshFettersInfo(nil)  
            end, self._targetCardId)

            if checkNumber(cellCardData.cardId) == checkNumber(self._curFettersId) then
                self.curSelectIndex = index + 1
                scr:RefreshImgSelectStatu(true)
                scr:RefreshChooseStatu(true)
                scr:RefreshCurPos(1)
                self:RefeshFettersInfo(cellCardData)                
            end
            return
        elseif self.chooseCardStatus == Constants.ChooseCardStatus.Custom then
            scr:RefreshCustom(cellCardData, function()
                self:ChooseCustomCard(index, go)
            end, self._customSelectMap, self._customCheckSame)
            if self._customLimitNum == 1 then
                scr:RefreshCurrentGoStatu(false)
            end
        else
            scr:Refresh(cellCardData, function(isCanDel)
                if self.chooseCardStatus == Constants.ChooseCardStatus.FishHangeUp then
                    self:ChooseFishHangUpCards(index, go)
                else
                    self:ChooseCards(index, go, isCanDel)
                end
            end, self._curFishQueueId, self._curLevelId, self._teamIndex)
        end

        -------------------------------------------------

        if self.chooseCardStatus == Constants.ChooseCardStatus.FishAccompany then
            scr:RefreshCurrentGoStatu(checkNumber(self._curSelectCardId) == checkNumber(cellCardData.cardId))
            if checkNumber(self.curSelectIndex) == 0 and checkNumber(self._curSelectCardId) == checkNumber(cellCardData.cardId) then
                scr:RefreshChooseStatu(true)
                scr:RefreshImgSelectStatu(true)
                --scr:RefreshCurrentGoStatu(true)
                self.curSelectIndex = index + 1
                self:RefeshFishShowInfo(cellCardData)
            elseif checkNumber(self.curSelectIndex) == index + 1 then
                scr:RefreshChooseStatu(true)
                scr:RefreshImgSelectStatu(true)
                --scr:RefreshCurrentGoStatu(true)
                self:RefeshFishShowInfo(cellCardData)
            end
        elseif self.chooseCardStatus == Constants.ChooseCardStatus.FishHangeUp then
            scr:FillFishHangUpInfo()
        elseif self.chooseCardStatus == Constants.ChooseCardStatus.CatHouseTrain then
            scr:FillFishHangUpInfo()

        elseif self.chooseCardStatus == Constants.ChooseCardStatus.Entrust then
            scr:FillEntrustInfo()
        elseif self.chooseCardStatus == Constants.ChooseCardStatus.LadderCompetion then
            local isLocked = self._disableIdMap[tostring(cellCardData.cardId)] == true
            scr:RefreshLockedStatu(isLocked)
        --elseif self._curLevelId == Constants.SpecialQuestId.LadderStruggleId then
        --    scr:FillLadderStruggleInfo(self._curLevelId, self._teamIndex, self._upBuffData)
        else
            if self._curLevelType == Constants.IDType.QuestMaze then
                scr:FillMazeInfo()
            elseif self._curLevelType == Constants.IDType.QuestPatrolMaze then
                scr:FillPatrolMazeInfo(self._patrolMaze)
            elseif self._curLevelType == Constants.IDType.QuestGachaCoin then
                scr:FillGachaCoinInfo()
            --elseif self._curLevelType == Constants.IDType.QuestSeniorEquipCopy then
            --    scr:FillSeniorEquipCopyInfo()
            elseif self._curLevelType == Constants.IDType.QuestWorldBoss or self._curLevelType == Constants.IDType.QuestArena or self._curLevelType == Constants.IDType.QuestTrail then
                scr:FillWorldBosssInfo(self._curLevelId, self._teamIndex, self._upBuffData, self.upGroup)
            elseif self._curLevelType == Constants.IDType.QuestBambooChanllenge then
                local BambooUtils = import('Game.UI.FightReady.UIBamboo.BambooUtils')
                local activityId = BambooUtils.GetActivityId(self._activityUuid)
                local groupIds = BambooUtils.GetUpBuffGroupIds(activityId)
                
                local t = BambooUtils.GetAllUpData(groupIds)
                scr:FillUpInfo(t)
            elseif self._curLevelType == Constants.IDType.QuestTalent then
                scr:FillTalentInfo(self._upBuffData)
            elseif self._curLevelType == Constants.IDType.QuestChaoticRecall or self._curLevelType ==  Constants.IDType.MournBoss or self._curLevelType == Constants.IDType.MournTower
                    or self._curLevelType == Constants.IDType.BeginnerBoss
                    or self._curLevelType == Constants.IDType.ActivityCakeBoss or self._curLevelType == Constants.IDType.QuestMidFestivalBoss then
                scr:FillUpInfo(self._upBuffData)
            elseif self._curLevelType == Constants.IDType.JapaneseStoryBoss then
                scr:FillUpInfo(self._upBuffData)
            elseif self._curLevelType == Constants.IDType.CustomTrain then
                scr:FillUpInfo(self._upBuffData)
            end
        end

        if self.curSelectIndex == index + 1 then
            scr:RefreshImgSelectStatu(true)
            if self.chooseCardStatus == Constants.ChooseCardStatus.FishAccompany then
                self:RefeshFishShowInfo(cellCardData)
            elseif self.chooseCardStatus == Constants.ChooseCardStatus.CatHouseTrain then
                self:RefreshCatTrainShowInfo(cellCardData)
            elseif self.chooseCardStatus == Constants.ChooseCardStatus.Fetter then
            elseif self.chooseCardStatus == Constants.ChooseCardStatus.Custom then
            else
                self:RefeshCardShowInfo(cellCardData)
            end
        end
    end
end

--选择卡牌
---@param itemIndex integer
---@param go UIFightChooseCardsCardCellNode
---@param isCanDel boolean
function UIFightChooseCardsDialog:ChooseCards(itemIndex, go, isCanDel)
    if not itemIndex then
        return
    end
    local cellData = self.haveCard[itemIndex + 1]
    local isRefresh = true  --是否刷新任务信息
    local lastSelectInd = checkNumber(self.curSelectIndex)
    self.curSelectIndex = checkInt(itemIndex) + 1
    if go then
        local bufferTeam = teamComponent:GetBufferTeam()
        --print("choose------>>"..table.dump(cellData))
        local key = teamComponent:GetTeamCardKey(bufferTeam, cellData.id)
        --print("bufferTeam------>>"..table.dump(bufferTeam))
        local memberData = teamComponent:GetTeamCardData(bufferTeam, cellData.id)

        -- 禁用卡牌不许选中
        if cellData.usable and cellData.usable == 0 then
            GameUtils.Toast(localize("无法上阵该属性战斗员"))
            return
        end

        --锁死得机器人不能下
        if not memberData or checkNumber(memberData.type) ~= Constants.TeamMemberType.QuestLockHelperCard then
            --如果该队员已经再队伍中  下阵
            if key then
                --isRefresh = false
                if isCanDel then
                    local isDelete = true
                    local vo = QuestConfMgr:GetInstance():GetQuestVoById(self._curLevelId)
                    if vo then
                        --有上阵条件
                        if checkNumber(vo.roleRestrictions) > 0 then
                            local limitVo = QuestConfMgr:GetInstance():GetQuestTeamLimitVo(vo.roleRestrictions) or {}
                            for i = 1, 4 do
                                local type = limitVo["type"..i]
                                local armId = limitVo["arm"..i]

                                --检测目标类型
                                if checkNumber(type) == Constants.TeamLimitType.Must then
                                    if checkInt(armId) > 0 then
                                        if QuestConfMgr:GetInstance():CheckCardArmCondition(type, armId, cellData.cardId) then
                                            isDelete = false
                                        end
                                    end
                                end
                            end
                            if not isDelete then
                                GameUtils.Toast(localize("必要战斗员，不可替换"))
                            end
                        end
                    end
                    if isDelete then
                        teamComponent:DelTeamMember(bufferTeam, self:GetCardToTeamMemberData(cellData))
                        self:CatSubjoinAttrChanged(bufferTeam)
                    end
                end
            else
                local count = teamComponent:GetTeamMemberCount(bufferTeam)
                local maxNum = self:GetMaxSelectNum()

                if count >= maxNum then
                    --GameUtils.Toast(localize("队员已达到最大数量"))
                    --return
                else
                    -- 禁用卡不允许选择
                    if self._curLevelType == Constants.IDType.QuestAdvancedTraining then
                        local canUse = true
                        local questVo = QuestConfMgr:GetInstance():GetQuestVoById(self._curLevelId)   --关卡配置
                        local conditionData = QuestConfMgr:GetInstance():GetQuestConditionWithMoreCf(questVo.conditionId, questVo.conditionValue)
                        if conditionData.comparType == Constants.QuestConditionComparType.GreaterThan then
                            if checkNumber(cellData.star) < checkNumber(conditionData.value) then
                                canUse = false
                            end
                        elseif conditionData.comparType == Constants.QuestConditionComparType.LessThan then
                            if checkNumber(cellData.star) > checkNumber(conditionData.value) then
                                canUse = false
                            end
                        end
                        if not canUse then
                            GameUtils.Toast(conditionData.desc)
                            return
                        end
                    end
                    local isLocked = self._disableIdMap[tostring(cellData.cardId)] == true
                    if isLocked then
                        GameUtils.Toast(localize("当前武装为锁定状态，禁止选择"))
                        return
                    end

                    local isLimitCard = GameUtils.IsLimitCard(self._curLevelId,cellData.id,self._teamIndex)
                    --相同卡牌不允许上阵
                    if not teamComponent:IsCanJoinTeam(bufferTeam, cellData) then
                        if self._curLevelType == Constants.IDType.QuestMain then
                            GameUtils.Toast(localize("已有重复武装"))
                        else
                            GameUtils.Toast(localize("已有重复武装"))
                        end
                    elseif not isCanDel and isLimitCard then
                        GameUtils.Toast(localize("无法上阵受限战斗员"))
                    else
                        teamComponent:AddTeamMember(bufferTeam, self:GetCardToTeamMemberData(cellData))
                        self:CatSubjoinAttrChanged(bufferTeam)
                    end
                end
                --if self._curLevelType == Constants.IDType.QuestSeniorEquipCopy then
                --    local equipQuestComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.EquipQuestComponent)
                --    if CardUtils.GetCardXielizhi(cellData.cardId) > (equipQuestComp:GetCurQuestCostNum() - teamComponent:GetCurTeamXielizhi(teamComponent:GetBufferTeam())) then
                --        GameUtils.Toast(localize("该角色超出协力值上限"))
                --        return
                --    end
                --end
            end
        end
        
        self:RefeshCardKey()
        
        self:FillSelf(true)
    end
    
    -- 禁用卡不允许选择
    local isLocked = self._disableIdMap[tostring(cellData.cardId)] == true
    if isLocked then
        GameUtils.Toast(localize("当前武装为锁定状态，请取消选择"))
    end

    if checkNumber(lastSelectInd) >= 0 then
        go = self.ChooseCardsView:GetShownItemByItemIndex(lastSelectInd)
        if go then
            local lastScr = CfUtils.GetLuaScr(go, UIFightChooseCardsCardCellNode)
            if lastScr then
                lastScr:RefreshImgSelectStatu(false)
            end
        end
    end

    local curSelectInd = checkNumber(self.curSelectIndex)
    if checkNumber(curSelectInd) > 0 then
        go = self.ChooseCardsView:GetShownItemByItemIndex(curSelectInd-1)
        if go then
            local curScr = CfUtils.GetLuaScr(go, UIFightChooseCardsCardCellNode)
            if curScr then
                curScr:RefreshImgSelectStatu(true)
            end
        end
    end

    self:FreshCurTeamXielizhi()
    --刷新右边人物信息
    if isRefresh then
        if self.chooseCardStatus == Constants.ChooseCardStatus.FishAccompany then
            self:RefeshFishShowInfo(cellData)
        elseif self.chooseCardStatus == Constants.ChooseCardStatus.CatHouseTrain then
            self:RefreshCatTrainShowInfo(cellData)

        else
            self:RefeshCardShowInfo(cellData)
        end
    end

    self:FillChooseNumber()
    KCookie.Set("UIFightChooseCardsDialogSelectInd", checkNumber(self.curSelectIndex))

    -- 刷新情绪共鸣节点
    if not CardUtils.IsUseEmotionBonus(self.chooseCardStatus) then
        CfUtils.SetActive(self.FightTeamBonusNode, false)
    else
        CfUtils.SetActive(self.FightTeamBonusNode, true)
        GameUtils.RefreshLineupBonusNode(self.FightTeamBonusNode, teamComponent:GetBufferTeam(), false, false, true)
    end
end

