    end
    
    self:RefeshFettersInfo(cellData)
end

--钓鱼挂机选择卡牌
function UIFightChooseCardsDialog:ChooseFishHangUpCards(itemIndex, go)
    if not itemIndex then
        return
    end
    local cellData = self.haveCard[itemIndex + 1]

    local isRefresh = true  --是否刷新任务信息
    local lastSelectInd = checkNumber(self.curSelectIndex)
    self.curSelectIndex = checkInt(itemIndex) + 1
    if go then
        local id = cardComponent:GetIdByCardId(cellData.cardId)
        --没有这张卡
        if checkNumber(id) == 0 then
            
        else
            cellData = cardComponent:GetCardById(cardComponent:GetIdByCardId(cellData.cardId))
            local bufferTeam = teamComponent:GetBufferTeam()
            local key = teamComponent:GetTeamCardKey(bufferTeam, cellData.id)
            --如果该队员已经再队伍中  下阵
            if key then
                --isRefresh = false
                teamComponent:DelTeamMemberByPos(bufferTeam, key, self:GetCardToTeamMemberData(cellData))
            else
                local count = teamComponent:GetTeamMemberCount(bufferTeam)
                if count >= 4 then
                    GameUtils.Toast(localize("队员已达到最大数量"))
                    --return
                else
                    --相同卡牌不允许上阵
                    if not teamComponent:IsCanJoinTeam(bufferTeam, cellData) then
                        GameUtils.Toast(localize("已有相同的卡牌在队伍中"))
                    else
                        local dojo = FishingUtils.GetCardFishHangUpData(cellData.id)
                        if dojo and checkNumber(dojo.teamId) ~= self._curFishQueueId then
                            GameUtils.Toast(localize("该卡牌已经再队列中"))
                        else
                            local pos = FishingUtils.GetFishTeamFreePos(self._curFishQueueId, bufferTeam)
                            if checkNumber(pos) > 0 then
                                teamComponent:AddTeamMemberByPos(bufferTeam, pos, self:GetCardToTeamMemberData(cellData))
                            else
                                GameUtils.Toast(localize("解锁位置已达到最大"))
                                --return
                            end
                        end
                    end
                end
            end
            self:RefeshCardKey()
        end
    end

    if checkNumber(lastSelectInd) >= 0 then
        go = self.ChooseCardsView:GetShownItemByItemIndex(lastSelectInd)
        if go then
            local lastScr = CfUtils.GetLuaScr(go, UIFightChooseCardsCardCellNode)
            if lastScr then
                lastScr:RefreshImgSelectStatu(false)
            end
        end
    end

    local curSelectInd = checkNumber(self.curSelectIndex)
    if checkNumber(curSelectInd) >= 0 then
        go = self.ChooseCardsView:GetShownItemByItemIndex(curSelectInd)
        if go then
            local curScr = CfUtils.GetLuaScr(go, UIFightChooseCardsCardCellNode)
            if curScr then
                curScr:RefreshImgSelectStatu(true)
            end
        end
    end

    --刷新右边人物信息
    if isRefresh then
        self:RefeshFishShowInfo(cellData)
    end
end


