-- 选择自定义卡牌
function UIFightChooseCardsDialog:ChooseCustomCard(itemIndex, go)
    if self._customLimitNum == 1 then
        -- 单选
        self:ChooseCustomCardSingle(itemIndex)
        return 
    end
    
    local chooseCardDojo = self.haveCard[checkInt(itemIndex) + 1]
    local oldSelectIndex = checkInt(self.curSelectIndex)
    local newSelectIndex = checkInt(itemIndex) + 1
    local isRefreshLeft  = false  -- 是否刷新左侧信息
    
    local findSelectIdx = 0
    for selectIndex, cardId in ipairs(self._customSelectIds) do
        if tostring(chooseCardDojo.cardId) == tostring(cardId) then
            findSelectIdx = selectIndex
            break
        end
    end

    local updateSselectFunc = function(cardCellNode, isSselect)
        if cardCellNode then
            local cardCellNodeLua = CfUtils.GetLuaScr(cardCellNode, UIFightChooseCardsCardCellNode)
            if cardCellNodeLua then
                cardCellNodeLua:RefreshImgSelectStatu(isSselect)
            end
        end
    end

    -- 旧的卡牌的取消选中状态
    local oldCardCellNode = oldSelectIndex > 0 and self.ChooseCardsView:GetShownItemByItemIndex(oldSelectIndex - 1) or nil
    updateSselectFunc(oldCardCellNode, false)

    -- 最新的卡牌选中状态
    local newCardCellNode = newSelectIndex > 0 and self.ChooseCardsView:GetShownItemByItemIndex(newSelectIndex - 1) or nil
    updateSselectFunc(newCardCellNode, true)

    -------------------------------------------------
    -- remove select
    if findSelectIdx > 0 then
        local isRefreshOthers = findSelectIdx < #self._customSelectIds

        -- 选中卡牌id：移除id
        table.remove(self._customSelectIds, findSelectIdx)
        self._customSelectMap[tostring(chooseCardDojo.cardId)] = nil

        -- 更新选中的位置
        self.curSelectIndex = newSelectIndex

        -- 当前的cell：取消选中状态
        local curSelectGo = go
        if curSelectGo then
            ---@type UIFightChooseCardsCardCellNode
            local curScr = CfUtils.GetLuaScr(go, UIFightChooseCardsCardCellNode)
            if curScr then
                curScr:RefreshChooseStatu(false)
            end
        end

        -- 如果是移除的中间位置，则刷新其他cell的索引下标
        if self._customCheckSame or isRefreshOthers then
            -- 刷新位置的map缓存
            self._customSelectMap = {}
            for cardIndex, cardId in ipairs(self._customSelectIds) do
                self._customSelectMap[tostring(cardId)] = tostring(cardIndex)
            end
            -- 刷新全部cell
            self:RefeshCardKey()
        end
        
    -------------------------------------------------
    -- add select
    else
        -- 更新选中的位置
        self.curSelectIndex = newSelectIndex

        -- 左侧显示卡牌信息
        isRefreshLeft = true

        -- 刷新左侧面板
        if isRefreshLeft then
            self:RefeshCustomCardShowInfo(chooseCardDojo)
        end

        if #self._customSelectIds >= self._customLimitNum then
            GameUtils.Toast(localize("已达到最大选择数量"))
            return
        end

        if self._customCheckSame then
            -- 相同卡牌不允许上阵
            for _, cardId in ipairs(self._customSelectIds) do
                local vo1 = CardConfMgr:GetInstance():GetCardByRefId(cardId)
                local vo2 = CardConfMgr:GetInstance():GetCardByRefId(chooseCardDojo.cardId)
                if checkNumber(vo1.characterId) == checkNumber(vo2.characterId) then
                    GameUtils.Toast(localize("已有重复武装"))
                    return
                end
            end
        end

        -- 选中卡牌id：追加id
        table.insert(self._customSelectIds, chooseCardDojo.cardId)
        self._customSelectMap[tostring(chooseCardDojo.cardId)] = tostring(#self._customSelectIds)

        if self._customCheckSame then
            -- 刷新全部cell
            self:RefeshCardKey()
        else
            -- 当前的cell：设为选中状态
            local curSelectGo = go
            if curSelectGo then
                ---@type UIFightChooseCardsCardCellNode
                local curScr = CfUtils.GetLuaScr(go, UIFightChooseCardsCardCellNode)
                if curScr then
                    curScr:RefreshChooseStatu(true)
                    curScr:RefreshCurPos(#self._customSelectIds)
                end
            end
        end
    end    

    -- 更新选中卡牌数
    self:FillChooseCustomNumber()
end

-- 选择自定义卡牌(单选)
function UIFightChooseCardsDialog:ChooseCustomCardSingle(itemIndex)
    local go = nil
    local lastSelectInd = checkNumber(self.curSelectIndex)
    if checkNumber(lastSelectInd) > 0 then
        go = self.ChooseCardsView:GetShownItemByItemIndex(lastSelectInd - 1)
        if go then
            local lastScr = CfUtils.GetLuaScr(go, UIFightChooseCardsCardCellNode)
            if lastScr then
                lastScr:RefreshChooseStatu(false)

                lastScr:RefreshImgSelectStatu(false)
            end
        end
    end

    self.curSelectIndex = checkNumber(itemIndex) + 1
    local curSelectInd = checkNumber(self.curSelectIndex)
    if checkNumber(curSelectInd) > 0 then
        go = self.ChooseCardsView:GetShownItemByItemIndex(curSelectInd - 1)
        if go then
            local curScr = CfUtils.GetLuaScr(go, UIFightChooseCardsCardCellNode)
            if curScr then
                curScr:RefreshCurrentGoStatu(false)
                curScr:RefreshChooseStatu(true)
                curScr:RefreshImgSelectStatu(true)
            end
        end
    end

    local cellData = self.haveCard[self.curSelectIndex]
    self:RefeshCustomCardShowInfo(cellData)
    self._customSelectIds = {cellData.cardId}
    self._customSelectMap = {
        [tostring(cellData.cardId)] = 1
    }
end

--将一个卡牌信息转换为队伍队员信息
function UIFightChooseCardsDialog:GetCardToTeamMemberData(data)
    if not data then
        return data
    end
    ---@type TeamMemberDojo
    local t = nil
    data = checkTable(data)
    --目前只有迷宫会有机器人助战
    if self._curLevelType == Constants.IDType.QuestMaze then
        if data.isAssistant == Constants.MazeRole.AssistRole then
            t = CfUtils.GetTeamMemberData(Constants.TeamMemberType.HelperCard, data.id, data.cardId)
            return t
        end
    elseif self._curLevelType == Constants.IDType.QuestPatrolMaze then
        t = CfUtils.GetTeamMemberData(Constants.TeamMemberType.PatrolMazeCard, data.id, data.cardId) -- 海外夜巡迷宫全部是定制卡，不是身上的卡
        ---@type PatrolMazeAreaDojo @ 当前所在区域dojo
        local areaDojo = self._patrolMaze.areaDojo
        t.areaId = areaDojo.areaId  -- 必要的，teamComponent:GetTeamFightingPower 中使用
        return t
    elseif self._curLevelType == Constants.IDType.Fairyland then
        t = CfUtils.GetTeamMemberData(Constants.TeamMemberType.PlayerCardWithoutEquip, data.id, data.cardId)
        return t
    end

    t = CfUtils.GetTeamMemberData(Constants.TeamMemberType.PlayerCard, data.id)
    return t
end

