--刷新卡牌信息展示
function UIFightChooseCardsDialog:RefeshCardShowInfo(cardData, isShowEquip)
    if not isNull(self._uiFightChooseCardsLeftNode) then
        KTool.SetActive(self.NoSelect, false)
        
        if self._curLevelType == Constants.IDType.QuestPatrolMaze or self._curLevelType == Constants.IDType.Fairyland then
            self._uiFightChooseCardsLeftNode:RefreshLeftCustomInfo(cardData, {hideLevelUp = true, hideCardEquip = true})
            return
        end

        if cardData.isAssistant == Constants.MazeRole.AssistRole then
            local questVo = QuestConfMgr:GetInstance():GetQuestVoById(self._curLevelId)
            if questVo then
                local cardData = BattleHelperConfMgr:GetInstance():GetMainLevelHelper(questVo.petLineup, cardData.cardId)
                cardData.isAssistant = Constants.MazeRole.AssistRole
                self._uiFightChooseCardsLeftNode:RefreshLeftCustomInfo(cardData, {hideLevelUp = true})
                return
            end
        end
        self._uiFightChooseCardsLeftNode:RefreshLeftInfo(cardData, isShowEquip)

    end
end

