    if not isNull(filterNodeEnv) then
        local sortType = Constants.UISortType.Team
        if self.chooseCardStatus == Constants.ChooseCardStatus.CatHouseTrain then
            sortType = Constants.UISortType.CardTrain
        end
        filterNodeEnv:SetCallback(self.haveCard, function(data)
            if self.chooseCardStatus == Constants.ChooseCardStatus.FishAccompany then
                self.haveCard = self:GetFishAllSortCard(data)
            else
                self.haveCard = self:GetAllCard(data)
            end
            self:FreshGridView()
        end, sortType)

        if self.chooseCardStatus == Constants.ChooseCardStatus.FishAccompany or self.chooseCardStatus == Constants.ChooseCardStatus.FishHangeUp then
        end

        if self.chooseCardStatus == Constants.ChooseCardStatus.FishAccompany or self.chooseCardStatus == Constants.ChooseCardStatus.FishHangeUp then--or self.chooseCardStatu == Constants.ChooseCardStatus.CatHouseTrain then
            filterNodeEnv.selectIndex = 4
        else
            filterNodeEnv:SaveState(Constants.UICacheDataKeys.UICultivateEntryFilterState)
            filterNodeEnv:SaveCustomParams({patrolMaze = self._patrolMaze})
