function UIFightChooseCardsDialog:GetFettersAllSortCard(cardData)
    local t1 = {}
    local t2 = {}

    local curSelectVo = nil
    local cardAll = cardData
    for k, v in pairs(cardAll) do
        if not v.cardId  then
            v.cardId = v.refId
        end
        local fettersId = CardConfMgr:GetInstance():GetRoleCardSynergiesId(self._targetCardId, v.cardId)
        if fettersId > 0 then
            table.insert(t1, v)
        else
            table.insert(t2, v)
        end
    end

    local t = {}
    for k, v in pairs(t1) do
        table.insert(t, v)
    end
    for k, v in pairs(t2) do
        table.insert(t, v)
    end
    return t
end


function UIFightChooseCardsDialog:GetFishAllSortCard(cardData)
    local t1 = {}
    local t2 = {}

    local curSelectVo = nil
    local cardAll = cardData
    for k, v in pairs(cardAll) do
        if not v.cardId  then
            v.cardId = v.refId
        end
        if checkNumber(self._curSelectCardId) > 0 and checkNumber(self._curSelectCardId) == checkNumber(v.cardId) then
            curSelectVo = v
        else
            local isCanFish = FishingUtils.IsCardGetAndCanFishing(v.cardId)
            if isCanFish then
                table.insert(t1, v)
            --else
            --    table.insert(t2, v)
            end
        end
    end

    table.sort(t1, function(a, b)
        if checkNumber(a.rare) == checkNumber(b.rare) then
            local aa = cardComponent:GetCardById(cardComponent:GetIdByCardId(a.cardId))
            local bb = cardComponent:GetCardById(cardComponent:GetIdByCardId(b.cardId))

            return checkNumber(aa.star) > checkNumber(bb.star)
        else
            return checkNumber(a.rare) < checkNumber(b.rare)
        end
    end)
    table.sort(t2, function(a, b)
        return checkNumber(a.rare) < checkNumber(b.rare)
    end)
    local t = {}
    for k, v in pairs(t1) do
        table.insert(t, v)
    end
    for k, v in pairs(t2) do
        table.insert(t, v)
    end

    if curSelectVo then 
        table.insert(t, 1, curSelectVo)
    end
    return t
end

--获取列中所有的卡
function UIFightChooseCardsDialog:GetAllCard(cardData)
    if self.chooseCardStatus == Constants.ChooseCardStatus.Fetter then
        local t = self:GetFettersAllSortCard(cardData)
        return t
    end

    local cardAll = cardData

    local t = {}
    --筛选掉相同cardid的
    --不是委托
    if self.chooseCardStatus ~= Constants.ChooseCardStatus.Entrust then
        --如果有机器人
        if QuestConfMgr:GetInstance():IsQuestHasHelper(self._curLevelId) then
            --[[
            local teamCards = QuestConfMgr:GetInstance():GetQuestHelpers(self._curLevelId)
            for k, v in pairs(cardAll) do
                if teamComponent:IsCanJoinTeam(teamCards, v) then
                    table.insert(t, v)
                end
            end
            ]]
            t = cardAll
        else
            t = cardAll
        end
    else
        t = cardAll
    end

    local bufferTeam = teamComponent:GetBufferTeam()

    local t1 = {}
    local t2 = {}
    for k, v in pairs(t) do
        if checkNumber(teamComponent:GetTeamCardKey(bufferTeam, v.id)) == 0 then
            table.insert(t2, v)
        else
            table.insert(t1, v)
        end
    end

    if #t1 > 1 then
        for i = 1, #t1 - 1 do
            for j = i + 1, #t1 do
                local aData = teamComponent:GetTeamCardData(bufferTeam, t1[i].id)
                local bData = teamComponent:GetTeamCardData(bufferTeam, t1[j].id)
                
                local isChange = false
                if (checkNumber(aData.type) ~= Constants.TeamMemberType.QuestLockHelperCard) and (checkNumber(bData.type) == Constants.TeamMemberType.QuestLockHelperCard) then
                    isChange = true
                elseif (checkNumber(aData.type) == Constants.TeamMemberType.QuestLockHelperCard) and (checkNumber(bData.type) ~= Constants.TeamMemberType.QuestLockHelperCard) then

                else
                    local aKey = teamComponent:GetTeamCardKey(bufferTeam, t1[i].id)
                    local bKey = teamComponent:GetTeamCardKey(bufferTeam, t1[j].id)

                    isChange = checkNumber(aKey) > checkNumber(bKey)
                end
                if isChange then 
                    local data = t1[i]
                    t1[i] = t1[j]
                    t1[j] = data
                end
            end
        end
    end

    --[[
    table.sort(t1, function(a, b)
        local aKey = teamComponent:GetTeamCardKey(bufferTeam, a.id)
        local bKey = teamComponent:GetTeamCardKey(bufferTeam, b.id)
        return checkNumber(aKey) < checkNumber(bKey)
    end)
    ]]
    table.insertto(t1, t2)
    return t1
end

