--界面隐藏与显示
function UIFightChooseCardsDialog:OnUIFightChooseCardsDialogAct(body)
    if body and body.isTrue then
        --self:RefeshCardsData()
        --self:FillFilter()
        KTool.SetActive(self.controller.gameObject, true)
        --self.ChooseCardsView:SetListItemCount(table.count(self.haveCard))

        -- 改为内部 OnBackAction 方法实现了
        -- CfUtils.RefreshTopCommon(function()
        --     if checkNumber(self._backIsClose) == 1 then
        --         UIModule.CloseDialog(self.controller)
        --         Events.Broadcast(Constants.EventNames.UIEntrustBattleTeamDialogActive, { isTrue = true })
        --     else
        --         UIModule.BackDialog()
        --     end
        -- end, false)

        local lastData = self:GetHideData()
        local ind = -1
        if lastData then
            for k, v in pairs(self.haveCard) do
                if self.chooseCardStatus == Constants.ChooseCardStatus.FishAccompany then
                    if checkNumber(lastData.cardId) == checkNumber(v.cardId) then
                        self.haveCard[k] = cardComponent:GetCardById(cardComponent:GetIdByCardId(v.cardId))
                        lastData = self.haveCard[k]
                        ind = k - 1
                        break
                    end
                elseif self.chooseCardStatus == Constants.ChooseCardStatus.FishHangeUp then
                    if checkNumber(lastData.cardId) == checkNumber(v.cardId) then
                        self.haveCard[k] = cardComponent:GetCardById(cardComponent:GetIdByCardId(v.cardId))
                        lastData = self.haveCard[k]
                        ind = k - 1
                        break
                    end
                elseif self.chooseCardStatus == Constants.ChooseCardStatus.CatHouseTrain then
                    if checkNumber(lastData.refId) == checkNumber(v.refId) then
                        local cardDojo = cardComponent:GetCardById(cardComponent:GetIdByCardId(lastData.refId))
                        self.haveCard[k].star = cardDojo.star
                        lastData = self.haveCard[k]
                        ind = k - 1
                        local bufferTeam = teamComponent:GetBufferTeam()
                        for i, b in pairs(bufferTeam) do
                            if checkNumber(b.refId) == checkNumber(lastData.refId) then
                                b.star = cardDojo.star
                            end
                        end
                        self:CatSubjoinAttrChanged(bufferTeam)
                        break
                    end
                else
                    if checkNumber(lastData.id) == checkNumber(v.id) then
                        self.haveCard[k] = cardComponent:GetCardById(v.id)
                        lastData = self.haveCard[k]
                        ind = k - 1
                        break
                    end
                end
            end

            if self.chooseCardStatus == Constants.ChooseCardStatus.FishAccompany or self.chooseCardStatus == Constants.ChooseCardStatus.FishHangeUp then
                self:RefeshFishShowInfo(lastData)
            elseif self.chooseCardStatus == Constants.ChooseCardStatus.CatHouseTrain then
                self:RefreshCatTrainShowInfo(lastData)
            else
                self:RefeshCardShowInfo(lastData)
            end

            ind = checkNumber(ind)
            if ind >= 0 then
                local go = self.ChooseCardsView:GetShownItemByItemIndex(ind)
                if not isNull(go) then
                    local scr = CfUtils.GetLuaScr(go, UIFightChooseCardsCardCellNode)
                    if scr then
                        if self.chooseCardStatus == Constants.ChooseCardStatus.CatHouseTrain then
                            scr:RefreshCatTrain(lastData)
                        else
                            scr:RefreshBaseData(lastData)
                        end

                    end
                end
            end
        end
        self.Content.localPosition = Vector2(self.Content.localPosition.x, 0)

        self:FillSelf(true)
    else
        --[[
        local filterMB = GetLuaBehaviour(self.CommonFilterNode.gameObject, 'Game.Behaviours.UICommonFilterMB')
        if not isNull(filterMB) and not isNull(filterMB.Env) then
            ---@type UICommonFilterMB
            local filterNodeEnv = filterMB.Env
            filterNodeEnv:SaveState(Constants.UICacheDataKeys.UICultivateEntryFilterState)
        end
        ]]

        KTool.SetActive(self.controller.gameObject, false)

        local ind = checkNumber(self.curSelectIndex) -- + 1
        -- if self.chooseCardStatu == Constants.ChooseCardStatus.FishAccompany then
        --     ind = checkNumber(self.curSelectIndex) --TODO 从1开始算的？
        -- end
        local data = self.haveCard[ind]
        if data then
            if self.chooseCardStatus == Constants.ChooseCardStatus.FishAccompany then
                self._lastSelectId = data.cardId
            elseif self.chooseCardStatus == Constants.ChooseCardStatus.FishHangeUp then
                self._lastSelectId = data.cardId
            elseif self.chooseCardStatus == Constants.ChooseCardStatus.CatHouseTrain then
                self._lastSelectId = data.refId
            else
                self._lastSelectId = data.id
            end
        end
    end
end

function UIFightChooseCardsDialog:GetHideData()
    if not self.haveCard then
        return nil
    end
    for k, v in pairs(self.haveCard) do
        if self.chooseCardStatus == Constants.ChooseCardStatus.FishAccompany then
            if checkNumber(v.cardId) == checkNumber(self._lastSelectId) then
                return v
            end
        elseif self.chooseCardStatus == Constants.ChooseCardStatus.FishHangeUp then
            if checkNumber(v.cardId) == checkNumber(self._lastSelectId) then
                return v
            end
        elseif self.chooseCardStatus == Constants.ChooseCardStatus.CatHouseTrain then
            if checkNumber(v.refId) == checkNumber(self._lastSelectId) then
                return v
            end
        else
            if checkNumber(v.id) == checkNumber(self._lastSelectId) then
                return v
            end
        end
    end
    return nil
end

function UIFightChooseCardsDialog:OnChangeFetters()
    local cellData = self.haveCard[checkNumber(self.curSelectIndex)]
    local id = 0
    if cellData then
        id = cellData.id
    end
    teamComponent:ChangeTeamFettersByCardId(teamComponent:GetBufferTeam(), self._targetCardId, id)

    if AnnihilationUtils.QuestTypeIsAnnihilation(self._curLevelType) then
        local t = teamComponent:GetBufferTeam()

        local t1 = {
            {}
        }
        local cardsInfo = teamComponent:GetAllCardId(t, true)
        local maxNum = RegionQuestMgr:GetInstance():GetOwnTeamNum()
        if #cardsInfo > maxNum then
            for i =  #cardsInfo, maxNum + 1, -1 do
                table.remove(cardsInfo, i)
            end
        end
        t1[1].cardsInfo = cardsInfo
        t1[1].mergeSkill = 0
        
        local cardIds = table.serialize(t1)
        RegionQuestMgr:GetInstance():TeamReq({roomSet = cardIds})
        self._isSetTeamReq = true
    else
        if self:IsPresetTeam() then
            teamComponent:SetBufferTeamToTeamByTeamType(self._teamType, self.chooseCardStatus, self._teamIndex, self._entrustId, function()
                if self._confirmCb then self._confirmCb() end
                UIModule.BackDialog()
            end)
        else
            teamComponent:SetBufferTeamToTeam(self._curLevelId, self.chooseCardStatus, self._teamIndex, self._entrustId, function()
                if self._confirmCb then self._confirmCb() end
                UIModule.BackDialog()
            end)
        end
    end
end

--正常关卡选人确定
function UIFightChooseCardsDialog:OnBtnSure()
    --挂机
    if self.chooseCardStatus == Constants.ChooseCardStatus.FishHangeUp then
        ---@type FishingComponent
        local comp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.FishingComponent)
        comp:ChangeOffLineCardsReq(self._curFishQueueId, teamComponent:GetBufferTeam(), function()
            UIModule.BackDialog()
        end)
    --陪钓
    elseif self.chooseCardStatus == Constants.ChooseCardStatus.FishAccompany then
        if checkNumber(self.curSelectIndex) <= 0 then
            GameUtils.Toast(localize("选择一个卡牌"))
            return
        end
        local comp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.FishingComponent)
        local cellData = self.haveCard[self.curSelectIndex]
        local id = cardComponent:GetIdByCardId(cellData.cardId)
        if checkNumber(id) <= 0 then
            GameUtils.Toast(localize("该卡牌未解锁"))
            return
        end
        comp:FishingAddPartnerReq(self._curFishPlaceId, id, function()
            UIModule.BackDialog()
        end)
    elseif self.chooseCardStatus == Constants.ChooseCardStatus.DirectDraw then
        ---@type ActivityDirectDrawMgr
        local ActivityDirectDrawMgr = import("Game.Activity.ActivityDirectDraw.ActivityDirectDrawMgr"):GetInstance()
        if checkNumber(self._curSelectCardId) > 0 then
            ActivityDirectDrawMgr:ChangeResearchCard(self._curSelectCardId, function()
                KCookie.Set(Constants.DirectDrawResearchChooseChange, true)
                UIModule.BackDialog()
            end)
        else
            GameUtils.Toast(localize("请选择一个研究方向"))
        end
    --猫屋确定
    elseif self.chooseCardStatus == Constants.ChooseCardStatus.CatHouseTrain then
        --local min, max = CatHouseMgr:GetInstance():GetCatTrainLimit()
        --local curNum = teamComponent:GetTeamMemberCount(teamComponent:GetBufferTeam())
        --if curNum <= min then
        --    GameUtils.Toast(localize("最少选择_num_个武装", {_num_ = min}))
        --    return
        --end
        Events.Broadcast(Constants.EventNames.CatHouseCatTrainRolesSelectJump, false)
        Events.Broadcast(Constants.EventNames.CatHouseCatTrainRolesSet, teamComponent:GetBufferTeam())
        UIModule.BackDialog()
    --羁绊
    elseif self.chooseCardStatus == Constants.ChooseCardStatus.Fetter then
        local cellData = self.haveCard[checkNumber(self.curSelectIndex)]   
        local isCanChange = true
        if cellData then
            isCanChange = teamComponent:IsCanChangeTeamFettersCard(teamComponent:GetBufferTeam(), cellData.cardId)
        end 
        if isCanChange then
            self:OnChangeFetters()
        else
            GameUtils.SecondConfirm(localize("确认选择重复的羁绊吗？"), function()
                self:OnChangeFetters()
            end)
        end
    --自定义
    elseif self.chooseCardStatus == Constants.ChooseCardStatus.Custom then
        if #self._customSelectIds >= self._customLeastNum then
            if self._confirmCb then
                self._confirmCb(self._customSelectIds)
            end
            UIModule.BackDialog()
        else
            GameUtils.Toast(localize('请至少选择_num_个卡牌', {_num_ = self._customLeastNum}))
        end
        
    --歼灭战
    elseif AnnihilationUtils.QuestTypeIsAnnihilation(self._curLevelType) then
        local t = teamComponent:GetBufferTeam()

        local t1 = {
            {}
        }
        local cardsInfo = teamComponent:GetAllCardId(t, true)
        local maxNum = RegionQuestMgr:GetInstance():GetOwnTeamNum()
        if #cardsInfo > maxNum then
            for i =  #cardsInfo, maxNum + 1, -1 do
                table.remove(cardsInfo, i)
            end
        end
        t1[1].cardsInfo = cardsInfo
        t1[1].mergeSkill = 0
        
        local cardIds = table.serialize(t1)
        RegionQuestMgr:GetInstance():TeamReq({roomSet = cardIds})
        self._isSetTeamReq = true
        ---AppService:GetInstance():SendTcpData(Constants.Packets.TeamReq, {cardIds = cardIds})
    elseif self._curLevelType == Constants.IDType.ClubBoss or self._curLevelType == Constants.IDType.Fairyland then
        local t = teamComponent:GetBufferTeam()
        local isHaveLimitCard = false
        for i, v in pairs(t) do
            local isLimit = GameUtils.IsLimitCard(self._curLevelId,v.refId,self._teamIndex)
            if isLimit then
                isHaveLimitCard = true
                break
            end
        end

        if isHaveLimitCard then
            GameUtils.Toast(localize("无法上阵受限战斗员"))
        else
            teamComponent:SetBufferTeamToTeam(self._curLevelId, self.chooseCardStatus, self._teamIndex, self._entrustId, function()
                if self._confirmCb then self._confirmCb() end
                UIModule.BackDialog()
            end)
        end
    elseif self._curLevelType == Constants.IDType.QuestChaoticRecall then
        local t = teamComponent:GetBufferTeam()
        local isHaveLimitCard = false
        for i, v in pairs(t) do
            local isLimit = GameUtils.IsLimitCard(self._curLevelId,v.refId,self._teamIndex)
            if isLimit then
                isHaveLimitCard = true
                break
            end
        end

        if isHaveLimitCard then
            GameUtils.Toast(localize("无法上阵受限战斗员"))
        else
            teamComponent:SetBufferTeamToTeam(self._curLevelId, self.chooseCardStatus, self._teamIndex, self._entrustId, function()
                if self._confirmCb then self._confirmCb() end
                UIModule.BackDialog()
            end)
        end
    elseif self._curLevelType == Constants.IDType.QuestPatrolMaze then
        ---@type PatrolMazeAreaDojo @ 当前所在区域dojo
        local areaDojo = self._patrolMaze.areaDojo
        teamComponent:SetBufferTeamToTeam(self._curLevelId, self.chooseCardStatus, self._teamIndex, self._entrustId, function()
            if self._confirmCb then self._confirmCb() end
            UIModule.BackDialog()
        end)
    else
        if self:IsPresetTeam() then
            teamComponent:SetBufferTeamToTeamByTeamType(self._teamType, self.chooseCardStatus, self._teamIndex, self._entrustId, function()
                if self._confirmCb then self._confirmCb() end
                UIModule.BackDialog()
            end)
        else
            teamComponent:SetBufferTeamToTeam(self._curLevelId, self.chooseCardStatus, self._teamIndex, self._entrustId, function()
                if self._confirmCb then self._confirmCb() end
                UIModule.BackDialog()
            end)
        end
    end
end

