function UIFightChooseCardsDialog:OnHide()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        CS.Engine.Lib.KCookie.Set(Constants.UICacheDataKeys.IsShowBlackAnimation, { isShow = false }) --全部的数据
        cs_coroutine.yield_return(self:OnCaptureAction())
    end))
    return coWait
end

function UIFightChooseCardsDialog:OnFishHangUpTimeDown()
    if self.chooseCardStatus ~= Constants.ChooseCardStatus.FishHangeUp then
        return 
    end

    local maxNum = self.ChooseCardsView.totalItemCount
    for i = 1, maxNum do
        local go = self.ChooseCardsView:GetShownItemByItemIndex(i - 1)
        if not isNull(go) then
            local scr = CfUtils.GetLuaScr(go, UIFightChooseCardsCardCellNode)
            if scr then
                scr:RefreshEnergy()
            end
        end
    end
end

function UIFightChooseCardsDialog:IsPresetTeam()
    return self._curLevelId == 0 and self._teamType
end

function UIFightChooseCardsDialog:GetMaxSelectNum()
    local maxNum = 0
    if self:IsPresetTeam() then
        maxNum = teamComponent:GetMaxSelectNumByTeamType(self._teamType)
    else
        maxNum = teamComponent:GetMaxSelectNumByQuestId(self._curLevelId, self.chooseCardStatus, self._teamIndex)
        if AnnihilationUtils.QuestTypeIsAnnihilation(self._curLevelType) then
            maxNum = RegionQuestMgr:GetInstance():GetOwnTeamNum()
        elseif self._curLevelType == Constants.IDType.ActivityCrisis then
            local ActivityCrisisUtils = import('Game.Activity.CrisisContract.ActivityCrisisUtils')
            local entryData = ActivityCrisisUtils.GetActivityCrisisMgr():GetEntryData()
            maxNum = ActivityCrisisUtils.GetMaxTeamMember(entryData)
        end
    end
    return maxNum
end

function UIFightChooseCardsDialog:OnEquipmentUpdate()
    -- 更新卡牌装备数据
    for i, v in ipairs(self.haveCard) do
        local cardDojo = cardComponent:GetCardById(v.id)
        table.merge(v, cardDojo)
    end
    local data = self.haveCard[self.curSelectIndex]
    self:RefeshCardShowInfo(data)
    
    -- 更新一次战力
    local vo = QuestConfMgr:GetInstance():GetQuestVoById(self._curLevelId)   --关卡配置
    local proposalLevel = vo == nil and 0 or checkNumber(vo.proposalLevel)
    self._lastNum = teamComponent:GetTeamFightingPower(teamComponent:GetBufferTeam(), self._teamCats, vo)
    CfUtils.FillText(self.TxtNumber, self._lastNum)

    local isLowPower = (self._lastNum < proposalLevel)
    if self._curLevelType == Constants.IDType.QuestNightCatTower then
        isLowPower = false
    end
    CfUtils.SetUISwitchText(self.TxtNumber, isLowPower and 2 or 1)
end

function UIFightChooseCardsDialog:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        if KTool.IsActive(self.CommonFilterNode.gameObject) then
            self:FillFilterByCo()
        end
    end))
    return coWait
end

function UIFightChooseCardsDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local initParams = self.controller.Argument.parameters
        if self.chooseCardStatus == Constants.ChooseCardStatus.Custom then
            initParams._curSelectIndex  = self.curSelectIndex
            initParams._customSelectIds = table.serialize(self._customSelectIds)
        else
            if self._patrolMaze ~= nil then
                initParams._bufferTeam = teamComponent:GetBufferTeam()
            end
        end

        if self.chooseCardStatus == Constants.ChooseCardStatus.CatHouseTrain then
            Events.Broadcast(Constants.EventNames.CatHouseCatTrainRolesSelectJump, false)
        end
        Events.RemoveListener(Constants.EventNames.FightChooseCardsDialogAct, self.EventUIFightChooseCardsDialogAct)
        Events.RemoveListener(Constants.EventNames.FishHangUpTimeDown, self.EventFishHangUpTimeDown)
        Events.RemoveListener(Constants.EventNames.RegionTeamSet, self.EventRegionTeamSet)
        Events.RemoveListener(Constants.EventNames.EquipmentPresetDialogUpdate, self.EventEquipmentUpdate)

        self.EventUIFightChooseCardsDialogAct = nil
        teamComponent:ClearBufferTeam()
        KCookie.RemoveAllListener(Constants.UICacheDataKeys.UICultivateEntryFilterState)
        if self._closeCb then
            self._closeCb()
        end
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return UIFightChooseCardsDialog